from PIL import Image
im=Image.open('/app/chess_board.png').convert('RGB')
# save upscaled crops of rank8 and rank5 for our own ascii detailed binary; print bounding boxes
from collections import Counter
for r in range(8):
  for f in range(8):
    t=im.crop((f*80,r*80,(f+1)*80,(r+1)*80))
    c=Counter(t.getdata()); bg=c.most_common(1)[0][0]
    xs=[];ys=[]
    for y in range(80):
      for x in range(80):
        p=t.getpixel((x,y))
        if max(abs(p[i]-bg[i]) for i in range(3))>25:
          xs.append(x);ys.append(y)
    if len(xs)>100:
      print(chr(97+f)+str(8-r), 'bbox',min(xs),min(ys),max(xs),max(ys),'size',max(xs)-min(xs)+1,max(ys)-min(ys)+1,'n',len(xs))
